  if (selectedSection == section) return;
  final int gen = ++_sectionGen;
  bool stale() => gen != _sectionGen || isClosed;
  // ... existing code up to emit(MoGetQuoteSectionChangeLoading(section));
  if (assetType == MoGetQuoteAssetType.futures) {
    await selectFuturesExpiry(section.label);
    if (!stale()) emit(MoGetQuoteSectionChanged(section));
    return;
  }
  await _loadSectionData(section);
  if (!stale()) emit(MoGetQuoteSectionChanged(section));
}
